"""
Codebase seed — Minimal Flask Todo API (tier 1, good seams)

A single-file Flask app with clean structure: models, routes, error handling.
Designed as a baseline for multi-session stories.
"""

from flask import Flask, request, jsonify, g
from functools import wraps
from werkzeug.security import check_password_hash
import os
import jwt

from repositories import get_db, UserRepository, TaskRepository
from tasks import send_notification_email

app = Flask(__name__)

app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY", "dev-secret-key")

user_repo = UserRepository()
task_repo = TaskRepository()


def init_db():
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS users ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  username TEXT NOT NULL UNIQUE,"
            "  password_hash TEXT NOT NULL"
            ")"
        )
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending',"
            "  created_at TEXT NOT NULL,"
            "  owner_id INTEGER REFERENCES users(id)"
            ")"
        )
        cols = [r[1] for r in conn.execute("PRAGMA table_info(tasks)").fetchall()]
        if "owner_id" not in cols:
            conn.execute(
                "ALTER TABLE tasks ADD COLUMN owner_id INTEGER REFERENCES users(id)"
            )
        conn.commit()


# ── Auth helpers ──────────────────────────────────────────────

def get_authenticated_user() -> dict | None:
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        return None
    token = auth[len("Bearer "):]
    try:
        payload = jwt.decode(token, app.config["SECRET_KEY"], algorithms=["HS256"])
    except jwt.PyJWTError:
        return None
    user_id = payload.get("sub")
    if user_id is None:
        return None
    return user_repo.get_by_id(user_id)


def require_auth(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        user = get_authenticated_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.user = user
        return f(*args, **kwargs)
    return wrapper


# ── Notifications ──────────────────────────────────────────────

def dispatch_completion_email(user_email: str, task_title: str) -> None:
    """Queue a notification email asynchronously via Celery."""
    send_notification_email.delay(user_email, task_title)


# ── Routes ─────────────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    if not username or not password:
        return jsonify({"error": "username and password are required"}), 400
    if user_repo.get_by_username(username) is not None:
        return jsonify({"error": "username already exists"}), 409
    user = user_repo.create_user(username, password)
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    user = user_repo.get_by_username(username)
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid credentials"}), 401
    token = jwt.encode(
        {"sub": user["id"]}, app.config["SECRET_KEY"], algorithm="HS256"
    )
    return jsonify({"token": token})


@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks():
    return jsonify(task_repo.get_tasks_by_owner(owner_id=g.user["id"]))


@app.route("/tasks", methods=["POST"])
@require_auth
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title", "").strip()
    if not title:
        return jsonify({"error": "title is required"}), 400
    task = task_repo.create_task(title, owner_id=g.user["id"])
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def show_task(task_id: int):
    task = task_repo.get_task(task_id, owner_id=g.user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    existing = task_repo.get_task(task_id, owner_id=g.user["id"])
    task = task_repo.update_task(
        task_id,
        owner_id=g.user["id"],
        title=data.get("title"),
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    if (
        existing is not None
        and existing["status"] != "completed"
        and task["status"] == "completed"
    ):
        dispatch_completion_email(g.user["username"], task["title"])
    return jsonify(task)


init_db()

if __name__ == "__main__":
    app.run(debug=True)

"""Repository pattern data access layer.

All SQLite queries live in repository classes. Route handlers interact
with repositories instead of raw SQL.
"""

import os
import sqlite3
from abc import ABC, abstractmethod
from datetime import datetime

from werkzeug.security import generate_password_hash


def get_db():
    conn = sqlite3.connect(os.environ.get("DATABASE", "todos.db"))
    conn.row_factory = sqlite3.Row
    return conn


class BaseRepository(ABC):
    """Abstract base repository with common CRUD operations."""

    @property
    @abstractmethod
    def table(self) -> str:
        """Name of the database table this repository manages."""

    def __init__(self, db=None):
        self._db = db if db is not None else get_db()

    def _row_to_dict(self, row):
        return dict(row) if row is not None else None

    def _rows_to_dicts(self, rows):
        return [dict(r) for r in rows]

    def get_by_id(self, record_id: int, **scope) -> dict | None:
        """Fetch a single record by id, optionally scoped by extra columns."""
        query = f"SELECT * FROM {self.table} WHERE id = ?"
        params = [record_id]
        for column, value in scope.items():
            query += f" AND {column} = ?"
            params.append(value)
        with self._db:
            row = self._db.execute(query, params).fetchone()
        return self._row_to_dict(row)

    def get_many(self, *, order_by: str | None = None, **filters) -> list[dict]:
        """Fetch all records matching filters, optionally ordered."""
        query = f"SELECT * FROM {self.table}"
        params = []
        if filters:
            clauses = [f"{column} = ?" for column in filters]
            query += " WHERE " + " AND ".join(clauses)
            params.extend(filters.values())
        if order_by:
            query += f" ORDER BY {order_by}"
        with self._db:
            rows = self._db.execute(query, params).fetchall()
        return self._rows_to_dicts(rows)

    def create(self, **values) -> dict:
        """Insert a record and return it as a dict."""
        columns = ", ".join(values.keys())
        placeholders = ", ".join("?" for _ in values)
        with self._db:
            cursor = self._db.execute(
                f"INSERT INTO {self.table} ({columns}) VALUES ({placeholders})",
                list(values.values()),
            )
            record_id = cursor.lastrowid
        return self.get_by_id(record_id)

    def update(self, record_id: int, **values) -> dict | None:
        """Update a record by id and return the updated record (or None)."""
        if not values:
            return self.get_by_id(record_id)
        assignments = ", ".join(f"{column} = ?" for column in values)
        with self._db:
            self._db.execute(
                f"UPDATE {self.table} SET {assignments} WHERE id = ?",
                list(values.values()) + [record_id],
            )
        return self.get_by_id(record_id)

    def delete(self, record_id: int) -> None:
        """Delete a record by id."""
        with self._db:
            self._db.execute(
                f"DELETE FROM {self.table} WHERE id = ?", (record_id,)
            )


class UserRepository(BaseRepository):
    """Repository for the users table."""

    @property
    def table(self) -> str:
        return "users"

    def create_user(self, username: str, password: str) -> dict:
        """Create a user and return a public dict (no password hash)."""
        password_hash = generate_password_hash(password)
        user = self.create(username=username, password_hash=password_hash)
        return {"id": user["id"], "username": user["username"]}

    def get_by_username(self, username: str) -> dict | None:
        """Fetch a single user by username."""
        users = self.get_many(username=username)
        return users[0] if users else None


class TaskRepository(BaseRepository):
    """Repository for the tasks table."""

    @property
    def table(self) -> str:
        return "tasks"

    def create_task(self, title: str, owner_id: int) -> dict:
        """Create a task with pending status and current timestamp."""
        now = datetime.utcnow().isoformat()
        return self.create(
            title=title, status="pending", created_at=now, owner_id=owner_id
        )

    def get_tasks_by_owner(self, owner_id: int) -> list[dict]:
        """Fetch all tasks for an owner, newest first."""
        return self.get_many(owner_id=owner_id, order_by="created_at DESC")

    def get_task(self, task_id: int, owner_id: int | None = None) -> dict | None:
        """Fetch a single task, optionally scoped to an owner."""
        if owner_id is None:
            return self.get_by_id(task_id)
        return self.get_by_id(task_id, owner_id=owner_id)

    def update_task(
        self,
        task_id: int,
        owner_id: int,
        title: str | None = None,
        status: str | None = None,
    ) -> dict | None:
        """Update a task owned by owner_id and return the updated record."""
        task = self.get_task(task_id, owner_id=owner_id)
        if task is None:
            return None
        values = {}
        if title is not None:
            values["title"] = title
        if status is not None:
            values["status"] = status
        if not values:
            return task
        return self.update(task_id, **values)

