import app as app_module

LIMIT = 5


def register(client, username, password):
    return client.post(
        "/auth/register", json={"username": username, "password": password}
    )


def login(client, username, password):
    return client.post(
        "/auth/login", json={"username": username, "password": password}
    )


def auth_headers(client, username, password="secret"):
    register(client, username, password)
    resp = login(client, username, password)
    return {"Authorization": f"Bearer {resp.get_json()['token']}"}


def test_default_limit_is_100_per_minute():
    limits = [str(l.limit) for l in app_module.limiter.default_limits]
    assert "100 per minute" in limits


def test_rate_limit_enforced_per_user(client):
    headers = auth_headers(client, "rl_alice")
    for _ in range(LIMIT):
        resp = client.get("/tasks", headers=headers)
        assert resp.status_code == 200
    resp = client.get("/tasks", headers=headers)
    assert resp.status_code == 429


def test_429_includes_retry_after(client):
    headers = auth_headers(client, "rl_bob")
    for _ in range(LIMIT):
        client.get("/tasks", headers=headers)
    resp = client.get("/tasks", headers=headers)
    assert resp.status_code == 429
    assert "Retry-After" in resp.headers
    assert int(resp.headers["Retry-After"]) > 0


def test_rate_limit_is_per_user(client):
    alice = auth_headers(client, "rl_carol")
    bob = auth_headers(client, "rl_dave")
    for _ in range(LIMIT):
        client.get("/tasks", headers=alice)
    assert client.get("/tasks", headers=alice).status_code == 429
    assert client.get("/tasks", headers=bob).status_code == 200
    assert client.get("/tasks", headers=bob).status_code == 200


def test_rate_limit_applies_to_all_endpoints(client):
    register(client, "rl_eve", "secret")
    for _ in range(LIMIT):
        resp = login(client, "rl_eve", "wrong")
        assert resp.status_code == 401
    resp = login(client, "rl_eve", "wrong")
    assert resp.status_code == 429

def register(client, username, password):
    return client.post(
        "/auth/register", json={"username": username, "password": password}
    )


def login(client, username, password):
    return client.post(
        "/auth/login", json={"username": username, "password": password}
    )


def auth_headers(client, username="alice", password="secret"):
    register(client, username, password)
    resp = login(client, username, password)
    return {"Authorization": f"Bearer {resp.get_json()['token']}"}


def create_tasks(client, count, username="alice"):
    headers = auth_headers(client, username)
    for i in range(count):
        client.post("/tasks", json={"title": f"task {i}"}, headers=headers)
    return headers


def test_default_limit_returns_first_page(client):
    headers = create_tasks(client, 25)
    resp = client.get("/tasks", headers=headers)
    assert resp.status_code == 200
    body = resp.get_json()
    assert len(body["data"]) == 20
    assert body["total"] == 25
    assert body["next_cursor"] == str(body["data"][-1]["id"])
    assert body["data"][0]["title"] == "task 24"
    assert body["data"][-1]["title"] == "task 5"


def test_cursor_paginates_through_all_tasks(client):
    headers = create_tasks(client, 25)
    seen = []
    cursor = None
    while True:
        url = "/tasks?limit=10"
        if cursor is not None:
            url += f"&cursor={cursor}"
        body = client.get(url, headers=headers).get_json()
        assert len(body["data"]) <= 10
        seen.extend(t["id"] for t in body["data"])
        cursor = body["next_cursor"]
        if cursor is None:
            break
    assert len(seen) == 25
    assert len(set(seen)) == 25


def test_limit_param_clamped_to_max(client):
    headers = create_tasks(client, 25)
    body = client.get("/tasks?limit=1000", headers=headers).get_json()
    assert len(body["data"]) == 25
    assert body["total"] == 25


def test_limit_below_one_clamped_to_one(client):
    headers = create_tasks(client, 5)
    body = client.get("/tasks?limit=0", headers=headers).get_json()
    assert len(body["data"]) == 1


def test_invalid_limit_returns_400(client):
    headers = auth_headers(client)
    resp = client.get("/tasks?limit=abc", headers=headers)
    assert resp.status_code == 400
    assert "error" in resp.get_json()


def test_invalid_cursor_returns_400(client):
    headers = auth_headers(client)
    resp = client.get("/tasks?cursor=notanint", headers=headers)
    assert resp.status_code == 400
    assert "error" in resp.get_json()


def test_cursor_beyond_end_returns_empty_page(client):
    headers = create_tasks(client, 3)
    body = client.get("/tasks?cursor=99999", headers=headers).get_json()
    assert body["data"] == []
    assert body["next_cursor"] is None
    assert body["total"] == 3


def test_total_counts_only_owners_tasks(client):
    alice = create_tasks(client, 3, username="alice")
    create_tasks(client, 5, username="bob")
    body = client.get("/tasks", headers=alice).get_json()
    assert body["total"] == 3
    assert len(body["data"]) == 3

